const fs=require('fs'),vm=require('vm'),assert=require('assert');const input=JSON.parse(fs.readFileSync(0,'utf8'));let handler,updated=0,timers=0,exited=0;const state={player:{extra:{allServerBattle:{}}}};const scene={instance:{viewResourcePanel:{isPanel:false},updateBattle_:()=>updated++,autoUpdateCD_:()=>timers++,onExitBattle_:()=>exited++}};
vm.runInNewContext(input.source,{serverMain:state,socket:{on:(name,fn)=>{assert.equal(name,'onAllServerBattle');handler=fn}},require:()=>scene});handler(input.payload);assert.equal(state.player.extra.allServerBattle.towerNo,5);assert.equal(updated,1);assert.equal(timers,1);handler({isEnd:true});assert.equal(exited,1);process.stdout.write(JSON.stringify({towerNo:state.player.extra.allServerBattle.towerNo,updated,exited}));
